WITH temp_view_0 AS (
SELECT /*+ materialize */ F0_0.ALLOCATION_ID AS ALLOCATION_ID, F0_0.ACCOUNT_ID AS ACCOUNT_ID, F0_0.TRANSACTION_ID AS TRANSACTION_ID, F0_0.STATEMENT_ID AS STATEMENT_ID, F0_0.PAYMENT_DATE AS PAYMENT_DATE, F0_0.TOTAL_PAYMENT AS TOTAL_PAYMENT, F0_0.MINIMUM_PAYMENT_PORTION AS MINIMUM_PAYMENT_PORTION, F0_0.EXCESS_PAYMENT_AMOUNT AS EXCESS_PAYMENT_AMOUNT, F0_0.PURCHASE_ALLOCATION AS PURCHASE_ALLOCATION, F0_0.CASH_ADVANCE_ALLOCATION AS CASH_ADVANCE_ALLOCATION, F0_0.BALANCE_TRANSFER_ALLOCATION AS BALANCE_TRANSFER_ALLOCATION, F0_0.PROMO_ALLOCATION AS PROMO_ALLOCATION, F0_0.ALLOCATION_ID AS PROV_PAYMENT__ALLOCATIONS_ALLOCATION__ID, F0_0.ACCOUNT_ID AS PROV_PAYMENT__ALLOCATIONS_ACCOUNT__ID, F0_0.TRANSACTION_ID AS PROV_PAYMENT__ALLOCATIONS_TRANSACTION__ID, F0_0.STATEMENT_ID AS PROV_PAYMENT__ALLOCATIONS_STATEMENT__ID, F0_0.PAYMENT_DATE AS PROV_PAYMENT__ALLOCATIONS_PAYMENT__DATE, F0_0.TOTAL_PAYMENT AS PROV_PAYMENT__ALLOCATIONS_TOTAL__PAYMENT, F0_0.MINIMUM_PAYMENT_PORTION AS PROV_PAYMENT__ALLOCATIONS_MINIMUM__PAYMENT__PORTION, F0_0.EXCESS_PAYMENT_AMOUNT AS PROV_PAYMENT__ALLOCATIONS_EXCESS__PAYMENT__AMOUNT, F0_0.PURCHASE_ALLOCATION AS PROV_PAYMENT__ALLOCATIONS_PURCHASE__ALLOCATION, F0_0.CASH_ADVANCE_ALLOCATION AS PROV_PAYMENT__ALLOCATIONS_CASH__ADVANCE__ALLOCATION, F0_0.BALANCE_TRANSFER_ALLOCATION AS PROV_PAYMENT__ALLOCATIONS_BALANCE__TRANSFER__ALLOCATION, F0_0.PROMO_ALLOCATION AS PROV_PAYMENT__ALLOCATIONS_PROMO__ALLOCATION
FROM PAYMENT_ALLOCATIONS F0_0)
SELECT F0_0.ALLOCATION_ID AS ALLOCATION_ID, F0_0.ACCOUNT_ID AS ACCOUNT_ID, F0_0.TRANSACTION_ID AS TRANSACTION_ID, F0_0.STATEMENT_ID AS STATEMENT_ID, F0_0.PAYMENT_DATE AS PAYMENT_DATE, F0_0.TOTAL_PAYMENT AS TOTAL_PAYMENT, F0_0.MINIMUM_PAYMENT_PORTION AS MINIMUM_PAYMENT_PORTION, F0_0.EXCESS_PAYMENT_AMOUNT AS EXCESS_PAYMENT_AMOUNT, F0_0.PURCHASE_ALLOCATION AS PURCHASE_ALLOCATION, (CASE  WHEN (F0_0.ALLOCATION_ID = 'ALLOC0000002') THEN 100 ELSE F0_0.CASH_ADVANCE_ALLOCATION END) AS CASH_ADVANCE_ALLOCATION, F0_0.BALANCE_TRANSFER_ALLOCATION AS BALANCE_TRANSFER_ALLOCATION, F0_0.PROMO_ALLOCATION AS PROMO_ALLOCATION, F0_0.PROV_PAYMENT__ALLOCATIONS_ALLOCATION__ID AS PROV_PAYMENT__ALLOCATIONS_ALLOCATION__ID, F0_0.PROV_PAYMENT__ALLOCATIONS_ACCOUNT__ID AS PROV_PAYMENT__ALLOCATIONS_ACCOUNT__ID, F0_0.PROV_PAYMENT__ALLOCATIONS_TRANSACTION__ID AS PROV_PAYMENT__ALLOCATIONS_TRANSACTION__ID, F0_0.PROV_PAYMENT__ALLOCATIONS_STATEMENT__ID AS PROV_PAYMENT__ALLOCATIONS_STATEMENT__ID, F0_0.PROV_PAYMENT__ALLOCATIONS_PAYMENT__DATE AS PROV_PAYMENT__ALLOCATIONS_PAYMENT__DATE, F0_0.PROV_PAYMENT__ALLOCATIONS_TOTAL__PAYMENT AS PROV_PAYMENT__ALLOCATIONS_TOTAL__PAYMENT, F0_0.PROV_PAYMENT__ALLOCATIONS_MINIMUM__PAYMENT__PORTION AS PROV_PAYMENT__ALLOCATIONS_MINIMUM__PAYMENT__PORTION, F0_0.PROV_PAYMENT__ALLOCATIONS_EXCESS__PAYMENT__AMOUNT AS PROV_PAYMENT__ALLOCATIONS_EXCESS__PAYMENT__AMOUNT, F0_0.PROV_PAYMENT__ALLOCATIONS_PURCHASE__ALLOCATION AS PROV_PAYMENT__ALLOCATIONS_PURCHASE__ALLOCATION, F0_0.PROV_PAYMENT__ALLOCATIONS_CASH__ADVANCE__ALLOCATION AS PROV_PAYMENT__ALLOCATIONS_CASH__ADVANCE__ALLOCATION, F0_0.PROV_PAYMENT__ALLOCATIONS_BALANCE__TRANSFER__ALLOCATION AS PROV_PAYMENT__ALLOCATIONS_BALANCE__TRANSFER__ALLOCATION, F0_0.PROV_PAYMENT__ALLOCATIONS_PROMO__ALLOCATION AS PROV_PAYMENT__ALLOCATIONS_PROMO__ALLOCATION
FROM (SELECT * FROM temp_view_0) F0_0;


